// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 0);
        vm.prank(caller);
        bool succeeded;
        try c.sudicideAnyone() { succeeded = true; } catch { succeeded = false; }
        bool exists = address(c).code.length > 0;
        assertTrue(succeeded ? !exists : true);
    }
}
